record.field:
website = env.ref('florist.website_industry')
to_deactivate = [ 'website_event.opt_event_organizer_block', 'website_event.opt_event_share_block', 'website_event.opt_events_list_columns', 'website.header_call_to_action', 'website.header_search_box', 'website.header_text_element', 'website.homepage', 'website.contactus', ] to_activate = [ 'website_event.opt_event_description_cover_top', 'website.footer_copyright_content_width_fluid', 'website.footer_no_copyright', 'website.template_header_default_align_center' ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
menus = env['website.menu'] base_domain = [('website_id', '=', website.id)]
# Rename/reorder the default menu items menu_labels = [ ('/', 'Home', 10), ('/event', 'Events', 30), ('/contactus', 'Contact us', 60), ] for url, name, sequence in menu_labels: menu = menus.search(base_domain + [('url', '=', url)], limit=1) if menu: menu.write({'name': name, 'sequence': sequence})
